/**
 * PNG Living 3D City — animated foundation effects.
 * Three.js instance is injected: no CDN, imports, or fetch in this module.
 * Caller handles bundling Three.js for autonomous HTML.
 * Supports procedural mist, cyan energy, separately moving GLB debris.
 * Real arches/rocks/cornices are generated by finish_edges.py offline.
 */
export function installFoundationFX(THREE, object3d, options = {}) {
  const { camera = null, seed = 17, mist = true, energy = true,
          shards = true, quality = 'mobile' } = options;
  const root = new THREE.Group();
  root.name = 'foundation_fx_root';
  object3d.add(root);
  const box = new THREE.Box3().setFromObject(object3d);
  if (box.isEmpty()) return { root, update() {}, dispose() { root.removeFromParent(); } };
  const bounds = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const width = Math.max(1, bounds.x);
  const height = Math.max(1, bounds.y);
  const lowY = box.min.y + height * 0.10;
  const pieces = [];
  object3d.traverse(o => {
    if (o.isMesh && /^finish_floating_shard_/.test(o.name)) {
      const y = o.position.y, x = o.position.x;
      pieces.push({ object: o, x, y, phase: pieces.length * 1.57 + seed, speed: 0.12 + (pieces.length % 5) * .027 });
    }
  });

  const geometry = new THREE.PlaneGeometry(width * 1.2, Math.max(2,height * 0.32));
  const uniforms = {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(0x277dc9) },
    uOpacity: { value: quality === 'mobile' ? 0.27 : 0.36 },
  };
  const mat = new THREE.ShaderMaterial({
    uniforms, transparent: true, depthWrite: false, side: THREE.DoubleSide,
    blending: THREE.NormalBlending,
    vertexShader: `varying vec2 vUv; void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,
    fragmentShader: `
      uniform float uTime; uniform vec3 uColor; uniform float uOpacity;
      varying vec2 vUv;
      float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
      float noise(vec2 x){
        vec2 i=floor(x),f=fract(x);f=f*f*(3.-2.*f);
        return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),
                   mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.)),f.x),f.y);
      }
      void main(){
        vec2 p=vUv*vec2(3.9,2.2);
        float n=noise(p+vec2(uTime*.045,-uTime*.022))*.58
               +noise(p*2.37+uTime*.032)*.27
               +noise(p*5.19-uTime*.017)*.15;
        float radial=smoothstep(0.,.24,vUv.x)*smoothstep(1.,.76,vUv.x);
        float soft=smoothstep(0.,.26,vUv.y)*smoothstep(1.,.45,vUv.y);
        float a=uOpacity*radial*soft*smoothstep(.27,.74,n);
        gl_FragColor=vec4(uColor+(n*.15),a);
      }`
  });
  if (mist) {
    for (let i=0;i<3;i++) {
      const sheet = new THREE.Mesh(geometry, mat);
      sheet.name = 'foundation_live_mist_' + i;
      sheet.position.set(center.x, lowY - i * height*.055, center.z);
      sheet.rotation.y = (i / 3) * Math.PI;
      root.add(sheet);
    }
  }
  const beamMat = new THREE.MeshBasicMaterial({color:0x1b96ee,transparent:true,opacity:0.12,
                                               depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide});
  let beam;
  if (energy) {
    const g = new THREE.CylinderGeometry(Math.max(.02,width*.012),Math.max(.06,width*.055),
      height*.29,9,1,true);
    beam = new THREE.Mesh(g,beamMat);
    beam.name = 'foundation_blue_energy';
    beam.position.set(center.x, lowY - height*.19, center.z);
    root.add(beam);
  }
  return {
    root,
    update(timeSeconds) {
      uniforms.uTime.value = timeSeconds;
      if (beam) {beam.material.opacity = .09 + .04 * Math.sin(timeSeconds * 1.5);
                 beam.rotation.y = timeSeconds*.14;}
      if (shards) for (const p of pieces) {
        // Node-local reversible motion, not distortion of original source artwork.
        p.object.position.x = p.x + Math.sin(timeSeconds*p.speed+p.phase)*width*.012;
        p.object.position.y = p.y + Math.sin(timeSeconds*p.speed*1.4+p.phase)*height*.013;
        p.object.rotation.y = Math.sin(timeSeconds*p.speed+p.phase)*.12;
      }
      if (camera && root.children.length) {
        // Keep atmospheric planes cross-facing for orbit readability.
        const flat = camera.position.clone().sub(center); flat.y=0;
        if (flat.lengthSq() > .0001) root.rotation.y= Math.atan2(flat.x,flat.z)*.08;
      }
    },
    dispose() {
      root.removeFromParent();geometry.dispose();mat.dispose();
      if (beam) {beam.geometry.dispose();beamMat.dispose();}
    }
  };
}
